 void CheckArmRecovery(Assembly pack){
  var root=Make("RecoveringBody");var upper=Make("RecoveringUpper",root.transform).transform;upper.position=new Vector3(1,1,0);var elbow=Make("RecoveringElbow",upper).transform;var wrist=Make("RecoveringHand",elbow).transform;var middle=Make("mixamorig:RightHandMiddle1",wrist).transform;middle.localPosition=Vector3.forward*.08f;var thumb=Make("mixamorig:RightHandThumb1",wrist).transform;thumb.localPosition=new Vector3(.05f,0,.02f);
  var type=pack.GetType("ChainsawPrototype.ThirdPersonArm",true);var arm=Activator.CreateInstance(type,All,null,new object[]{wrist,root.transform},null);Call(arm,"Capture");elbow.position=upper.position+Vector3.down*.25f;wrist.position=upper.position+Vector3.down*.5f;Call(arm,"Capture");var goal=upper.position+new Vector3(0,-.3f,.3f);Call(arm,"Solve",goal,Quaternion.identity);Check(Vector3.Distance(wrist.position,goal)<.005f,"arm retries after an incomplete startup pose instead of remaining disabled until reequip");wrist.localRotation=Quaternion.Euler(12,-8,5);var localWrist=wrist.localRotation;Call(arm,"Capture");var hint=upper.position+new Vector3(.3f,-.2f,.1f);Call(arm,"SetBodyPose",hint);Call(arm,"Solve",goal,Quaternion.identity);Check(Quaternion.Angle(wrist.localRotation,localWrist)<.01f,"wrist follows the solved forearm while preserving its native local joint pose");var direction=(goal-upper.position).normalized;Check(Vector3.Dot(Vector3.ProjectOnPlane(elbow.position-upper.position,direction).normalized,Vector3.ProjectOnPlane(hint-upper.position,direction).normalized)>.999f,"elbow bend follows the body-space pose hint");
